#------------------Hidden back end functions that shouldn't be used outside of this file------------------
def __convert_map_and_move_to_object(objectMap: Union[dict, object]) -> object:
    if type(objectMap) is dict:
        objectMap = find_object(objectMap)
    return objectMap

def __convert_map_and_wait_for_object_to_exist(objectMap: Union[dict, object]) -> object:
    if type(objectMap) is dict:
        objectMap = wait_for_object_exists(objectMap)
    return objectMap

def __find_by_value_in_child_object_list(objectList: Tuple[object], *searchValue: str) -> object:
    """Checks all the searchValue strings exist in the current child object value from the list of
    child objects. If all strings are found return the matching child object.

    :param Tuple[object] objectList: Collection of objects
    :param str searchValue: String Value used to find an object. One or more searchValue string
    args can be passed in
    :return: found object
    :rtype: object
    """
    for child_object in objectList:
        if hasattr(child_object, 'value') and all(x in child_object.value for x in searchValue): #type: ignore
            return child_object

def __find_children_by_value_in_child_object_list(objectList: Tuple[object], *searchValue: str):
    """Checks all the searchValue strings exist in the current child object value from the list of
    child objects. If a searchValue string is found, add it to a new list of found child objects
    and return this list of matching child objects.

    :param Tuple[object] objectList: Collection of objects
    :param str searchValue: String Value used to find an object. One or more searchValue string
    args can be passed in
    :return: found object
    :rtype: object
    """
    found_list = []
    for child_object in objectList:
        if hasattr(child_object, 'value') and all(x in child_object.value for x in searchValue): #type: ignore
            found_list.append(child_object)
    return found_list

def __find_by_child_name_in_child_object_list(objectList: Tuple[object], searchValue: str):
    for child_object in objectList:
        if hasattr(child_object, 'name') and searchValue in child_object.name: #type: ignore
            return child_object

def __find_by_child_text_in_child_object_list(objectList: Tuple[object], searchValue: str, subset: bool=True):
    """Checks the searchValue string exists in(or exactly matches) any child object text in the list of
    child objects. If a searchValue string is found, return the child object, otherwise return None.

    :param Tuple[object] objectList: Collection of objects
    :param str searchValue: String Value used to find an object.
    :param bool subset: True: if the seachValue is subset of the child object text, or False: exactly matching.

    :return: found object
    :rtype: object
    """
    for child_object in objectList:
        if hasattr(child_object, 'text') and searchValue in child_object.text: #type: ignore
            if subset or searchValue == child_object.text: # type: ignore
                return child_object
            else:
                continue
    return None

def __find_by_exact_child_text_in_child_object_list(objectList: Tuple[object], searchValue: str):
    for child_object in objectList:
        if hasattr(child_object, 'text') and searchValue == child_object.text: #type: ignore
            return child_object

def __find_by_child_id_in_child_object_list(objectList: Tuple[object], searchValue: str):
    for child_object in objectList:
        if hasattr(child_object, 'id') and searchValue in child_object.id: #type: ignore
            return child_object

def __find_by_child_objects_type_in_child_object_list(objectList: Tuple[object], searchValue: str):
    found_list = []
    for child_object in objectList:
        if hasattr(child_object, 'type') and searchValue in child_object.type: #type: ignore
            found_list.append(child_object)
    return found_list

