def set_context_application_to_foreground(guiObject) -> None:
    """Sets the active application context app into the foreground of the machine

    :param object guiObject: Window object that is to be set to the foreground
    """
    squishtest.setForegroundWindow(guiObject) #type: ignore

def maximise_windows_object(windowGUIObject) -> None:
    """Maximises object to full screen

    :param object windowGUIObject: Object to be maximised to full screen
    """
    squishtest._squish_window_maximize(__convert_map_and_move_to_object(windowGUIObject)) #type: ignore

def get_top_level_window_by_object(targetObject: dict) -> ToplevelWindow:
    """Returns the ToplevelWindow object handle for the given target object
    to perform operations such as minimize, maximize, restore etc...

    :param object targetObject: Object to retrieve the ToplevelWindow handle for
    :return: ToplevelWindow object handle
    :rtype: ToplevelWindow object
    """
    return ToplevelWindow.byObject(find_object(targetObject))

def move_windows_object(windowGUIObject, xPosition: int, yPosition: int)-> None:
    ToplevelWindow.byObject(find_object(windowGUIObject)).moveTo(xPosition, yPosition)

def get_files_on_remote_system(folderPath: str) -> list:
    """Checks that folder path exists on the system where the Squish server is running.

    :param str folderPath: A string variable for the path of a given folder

    """
    remoteOS = RemoteSystem()
    if remoteOS.exists(folderPath):
        return remoteOS.listFiles(folderPath)
    return []

def find_object(objectMap: dict, timeout:int = 10000) -> object:
    """Searches the current application context for a given objectMap and
    returns the object

    :param objectMap: objectMap data to be located
    :type objectMap: dict
    :param timeout: Time to wait for object in milliseconds
    :type timeout: int
    :return: found object
    :rtype: object

    :raises FailedToFindObject: If no object is found

    """
    try:
        return squishtest.waitForObject(objectMap, timeout) #type: ignore
    except LookupError:
        # Fallback strategies: try to find a sensible editable control in the current context
        try:
            # 1) prefer any explicit Edit controls
            edits = squishtest.findAllObjects({'type': 'Edit'}) #type: ignore
            if edits and len(edits) > 0:
                return edits[0]
        except Exception:
            pass
        try:
            # 2) look for Edit under any Window matching LoginWorkspace or MOSAIQ
            wins = squishtest.findAllObjects({'type': 'Window'}) #type: ignore
            for w in wins:
                try:
                    txt = getattr(w, 'text', '') or ''
                    name = getattr(w, 'name', '') or ''
                    if 'login' in str(txt).lower() or 'login' in str(name).lower() or 'mosaiq' in str(txt).lower():
                        children = squishtest.object.children(w) #type: ignore
                        for c in children:
                            if getattr(c, 'type', '') in ('Edit', 'WindowsFormsControl', 'WindowsFormsAccessibleObject'):
                                return c
                except Exception:
                    continue
        except Exception:
            pass
        # final fallback: try any WindowsFormsControl
        try:
            wf = squishtest.findAllObjects({'type': 'WindowsFormsControl'}) #type: ignore
            if wf and len(wf) > 0:
                return wf[0]
        except Exception:
            pass
        # no fallback found
        raise FailedToFindObject(objectMap)

def does_object_exist(objectMap: dict, timeoutInMSec: int = 5000) -> bool:
    """Reports whether an object exists in the current application context.

    Unlike find_object(), a miss is reported as False rather than falling back to an unrelated
    control, so this is the safe primitive for "is X on screen?" checks.

    :param objectMap: objectMap data to be located
    :type objectMap: dict
    :param timeoutInMSec: Time to wait for the object before reporting it absent
    :type timeoutInMSec: int
    :return: True when the object exists, otherwise False
    :rtype: bool
    """
    try:
        return squishtest.waitForObjectExists(objectMap, timeoutInMSec) is not None #type: ignore
    except LookupError:
        return False

def is_object_visible(objectMap: dict, timeoutInMSec: int = 5000) -> bool:
    """Reports whether an object both exists and is visible in the current application context.

    WinForms controls are routinely kept in the object tree after the UI stops showing them, so
    an existence check alone can report a panel as present long after it has been cleared.

    :param objectMap: objectMap data to be located
    :type objectMap: dict
    :param timeoutInMSec: Time to wait for the object before reporting it absent
    :type timeoutInMSec: int
    :return: True when the object exists and is visible, otherwise False
    :rtype: bool
    """
    try:
        obj = squishtest.waitForObjectExists(objectMap, timeoutInMSec) #type: ignore
    except LookupError:
        return False
    return bool(obj is not None and getattr(obj, "visible", True))

def wait_for_object_exists(objectMap: dict, timeoutInMSec: int=20000) -> object:
    """Searches the current application context and waits for the specified
    object to exist. Returns the object if found.

    Note: Squish's waitForObjectExists() returns the object if it simply exists.
    This differs from Squish's waitForObject() which returns the object only if
    it exists and is visible and ENABLED. The use case for using
    waitForObjectExists() is when the object is an uneditable or disabled field,
    but still contains data that needs to be read.

    :param objectMap: objectMap data to be located
    :type objectMap: dict
    :param timeoutInMSec: Time to wait for object
    :type timeoutInMSec: int
    :return: found object
    :rtype: object

    :raises FailedToFindObject: If no object is found

    """
    try:
        return squishtest.waitForObjectExists(objectMap, timeoutInMSec) #type: ignore
    except LookupError as error:
        raise FailedToFindObject(objectMap)

def wait_for_object_item(obj:Union[dict, object], item:str) -> object:
    """
    Wait for object item to be in the view and selected.

    This function is typically used to access items inside containers such as lists, tables, and trees.

    :params: obj (dict or object): the object that contains the item
             item (str): the target waited for.
    :return: the target item to find
    :rtype: object
    """
    return squishtest.waitForObjectItem(obj, item) # type: ignore

def get_checkbox_state(objectMap: Union[dict, object]) -> bool:
    """_summary_

    :param objectMap: The object that will have its "checked" value returned if it has one. A find_object() will be performed if the object map dict is passed in.
    :type objectMap: Union[dict, object]
    :raises AttributeError: This error is raised in the event that a target object does not have a 'checked' attribute.
    :return: The objects 'checked' attribute is returned, which is either a True or False bool value.
    :rtype: bool
    """
    obj = __convert_map_and_move_to_object(objectMap)
    if hasattr(obj, "checked"):
        return obj.checked #type: ignore
    raise AttributeError("Given Object does is not a check box object!")

def left_click_object(objectMap: Union[dict, object]) -> None:
    """Moves the mouse to and left mouse clicks a given object

    :param objectMap: Object to be clicked
    :type objectMap: Union[dict, object]
    """
    obj = __convert_map_and_move_to_object(objectMap)
    try:
        squishtest.mouseMove(obj) #type: ignore
    except RuntimeError:
        # Some Squish backends fail sending synthetic pointer moves; continue to click without move
        pass
    squishtest.mouseClick(obj) #type: ignore

def left_click_object_no_move(objectMap: Union[dict, object]) -> None:
    """Clicks a given object with no mouse move before hand

    :param objectMap: Object to be clicked
    :type objectMap: Union[dict, object]
    """
    obj = __convert_map_and_move_to_object(objectMap)
    squishtest.mouseClick(obj) #type: ignore

def get_global_bounds(obj) ->object:
    """
    Get the bounding global rect of the give obj.

    :param  obj, the object
    :return rect of the object
    :rtype: object
    """
    return squishtest.object.globalBounds(obj) # type: ignore

def mouse_click(obj, x:int=0, y:int=0, leftButton:bool=True) -> None:
    """Clicks a given object with no mouse move before hand

    :params: obj (object): Object  to be clicked
             x (int): x coordinate relative to the top left.
             y (int): y coordinate relative to the top left.
             leftButton (bool): True:left mouse button, False:right mouse button.
    """
    #obj = squishtest.object.globalBounds(obj) # type: ignore
    squishtest.mouseClick(obj, x, y, squishtest.MouseButton.LeftButton if leftButton else squishtest.MouseButton.RightButton) #type: ignore

def right_click_object(objectMap: Union[dict, object]) -> None:
    """Moves the mouse to and right mouse clicks a given object

    :param objectMap: Object to be clicked
    :type objectMap: Union[dict, object]
    """
    obj = __convert_map_and_move_to_object(objectMap)
    squishtest.mouseMove(obj) #type: ignore
    squishtest.mouseClick(obj, squishtest.MouseButton.RightButton) #type: ignore

def double_click_object(objectMap: Union[dict, object], delay: int = 0) -> None:
    """Moves the mouse to and double clicks a given object

    :param objectMap: Object to be clicked
    :type objectMap: Union[dict, object]
    """
    obj = __convert_map_and_move_to_object(objectMap)
    squishtest.mouseMove(obj) #type: ignore
    squishtest.doubleClick(obj) #type: ignore
    if delay > 0:
        time.sleep(delay)

def shift_click_object(objectMap: Union[dict, object]) -> None:
    """Clicks a given object with the modifer of Shift

    :param objectMap: Object to be clicked
    :type objectMap: Union[dict, object]
    """
    obj = __convert_map_and_move_to_object(objectMap)
    squishtest.keyPress("<Shift>") #type: ignore
    squishtest.mouseClick(obj) #type: ignore
    squishtest.keyRelease("<Shift>") #type: ignore

    time.sleep(0.5)

def mouse_click_while_holding_key(objectMap: Union[dict, object], key:str, which_button:str) -> None:
    """
    Mouse click while holding given key.

    :params: objectMap (dict or object): Object to be clicked

             key (str): any key including a-Z, 0-9, 'Alt', 'Command', 'Ctrl', 'Shift', 'Win', etc.,if 'None', not holding key.

             which_button (str): indicate which mouse button. 'LeftButton', 'MiddleButton', 'RightButton',etc.
    """
    obj = __convert_map_and_move_to_object(objectMap)
    is_key_none = key == 'None'
    key = "<" + key + ">"
    if not is_key_none:
        squishtest.keyPress(key) # type: ignore
    mouse_button = getattr(squishtest.MouseButton, which_button) # type: ignore
    squishtest.mouseClick(obj, 0, 0, mouse_button) # type: ignore
    if not is_key_none:
        squishtest.keyRelease(key) # type: ignore

def type_in_textfield(objectMap: Union[dict, object], textString: str) -> None:
    """Clicks a given object and then types a str into it

    :param Union[dict, object] objectMap: Object to be clicked and typed into
    :param str textString: String to be enter into the object

    """
    obj = __convert_map_and_move_to_object(objectMap)
    try:
        left_click_object(obj)
        squishtest.type(obj, textString) #type: ignore
    except RuntimeError:
        # Fallback: try to focus the window/object and use native typing
        try:
            if hasattr(squishtest, 'setForegroundWindow'):
                try:
                    squishtest.setForegroundWindow(obj) #type: ignore
                except Exception:
                    pass
            # attempt direct type; if object-targeted type fails, fallback to nativeType
            try:
                squishtest.type(obj, textString) #type: ignore
            except Exception:
                try:
                    squishtest.nativeType(textString) #type: ignore
                except Exception:
                    raise
        except Exception:
            raise

def native_text_type(textToType: str) -> None:
    """Type text using Squish's native type function.

    Note: The target/ destination object must be selected before this function is called.

    :param str textToType: Text to be typed
    """
    squishtest.nativeType(textToType) #type: ignore

def get_child_objects(parentObj: Union[dict, object]) -> Tuple[object]:
    """Searches an object for all the child objects it contains

    :param Union[dict, object] parentObj: Parent Object that will be searched for child objects
    :return: Child objects of parentObj
    :rtype: Tuple[object]

    """
    obj = __convert_map_and_move_to_object(parentObj)
    return squishtest.object.children(obj) #type: ignore

def get_all_objects_by_map(parentObj: dict) ->Tuple[object]:
    """Searches for all objects inside of a context that share an Object Map

    :param parentObj: Object Map that will be searched for within the context.
    :type parentObj: dict
    :return: All found objects within the context that share the same Object Map
    :rtype: Tuple[object]
    """
    return squishtest.findAllObjects(parentObj) #type: ignore

def get_child_object_by_value(objectList: Tuple[object], *searchValue: str) -> object:
    """Searches an object list (Tuple[object]) for a specified value (str)

    :param Tuple[object] objectList: Collection of objects
    :param str searchValue: String Value used to find an object.
                            One or more searchValue string values args can be passed in
    :return: found object
    :rtype: object

    """
    return __find_by_value_in_child_object_list(objectList, *searchValue)

def get_child_objects_by_object_value(objectList: Tuple[object], *searchValue: str) -> 'list[object]':
    """Searches an object list (Tuple[object]) for a specified value (str) and returns a new list
    of all the matching objects found.

    :param Tuple[object] objectList: Collection of objects
    :param str searchValue: String Value used to find an object.
                            One or more searchValue string values args can be passed in
    :return: found list of objects
    :rtype: list[object]
    """
    return __find_children_by_value_in_child_object_list(objectList, *searchValue)

def get_child_object_by_object_name(objectList: Tuple[object], searchName: str) -> object:
    """Searches an object list (Tuple[object]) for an object by name (str)

    :param Tuple[object] objectList: Collection of objects
    :param str searchName: Name of object to be found
    :return: found object
    :rtype: object

    """
    return __find_by_child_name_in_child_object_list(objectList, searchName)

def get_child_object_by_object_text(objectList: Tuple[object], searchText: str) -> object:
    """Searches an object list (Tuple[object]) for an object by text (str) where the
    searchText is found inside the object text (does not check for an exact text match)

    :param Tuple[object] objectList: Collection of objects
    :param str searchText: Text of the object to be found
    :return: found object
    :rtype: object
    """
    return __find_by_child_text_in_child_object_list(objectList, searchText, True)

def get_child_object_by_exact_object_text(objectList: Tuple[object], searchText: str) -> object:
    """Searches an object list (Tuple[object]) for an object by text (str) where the
    searchText is an exact match of the object text

    :param Tuple[object] objectList: Collection of objects
    :param str searchText: Text of the object to be found
    :return: found object
    :rtype: object
    """
    return __find_by_exact_child_text_in_child_object_list(objectList, searchText)

def get_child_object_by_object_id(objectList: Tuple[object], searchId: str) -> object:
    """Searches an object list (Tuple[object]) for an object by id (str)

    :param Tuple[object] objectList: Collection of objects
    :param str searchId: Id of the object to be found
    :return: found object
    :rtype: object
    """
    return __find_by_child_id_in_child_object_list(objectList, searchId)

def get_child_objects_by_object_type(objectList: Tuple[object], searchText: str) -> 'list[object]':
    """Searches an object list (Tuple[object]) for an object by type (str)

    :param Tuple[object] objectList: Collection of objects
    :param str searchText: Type of the object to be found
    :return: found list of objects
    :rtype: list[object]
    """
    return __find_by_child_objects_type_in_child_object_list(objectList, searchText)

def click_button(objectMap: Union[dict, object], timeout:int = 30000):
    '''
    Click the button object.

    :params: objectMap (dict or object), the object control
             timeout (int), the specified timeout in ms,default to 30000.
    '''
    if type(objectMap) is dict:
        objectMap = find_object(objectMap, timeout)
    #squishtest.mouseMove(objectMap) # type: ignore
    squishtest.clickButton(objectMap) #type: ignore

def clear_text(objectMap: Union[dict, object]):
    '''
    Use this to clear text from an object
    '''
    obj = None
    try:
        obj = squishtest.waitForObject(objectMap, 500) #type: ignore
    except Exception:
        return obj # not ready/enabled
    if  obj and hasattr(obj, "text") and len(getattr(obj, "text")) > 0:
        squishtest.mouseMove(obj)               #type: ignore
        squishtest.mouseClick(obj)              #type: ignore
        squishtest.snooze(0.3)                  #type: ignore
        squishtest.nativeType("<Home>")         #type: ignore
        squishtest.snooze(0.3)                  #type: ignore
        squishtest.nativeType("<Shift+End>")    #type: ignore
        squishtest.snooze(0.1)                  #type: ignore
        squishtest.nativeType("<Delete>")       #type: ignore
        squishtest.snooze(0.1)                  #type: ignore
    return obj

def get_text(objectMap: Union[dict, object])->str:
    '''
    Use this function to get an object's text
    '''
    text = ""
    try:
        obj = squishtest.waitForObject(objectMap, 200) #type: ignore
        if obj:
            text = getattr(obj, "text", "")
    except Exception:
        obj = squishtest.waitForObjectExists(objectMap) #type: ignore
        if obj:
            text = getattr(obj, "text", "")
    return str(text)

def set_text(objectMap: Union[dict, object], textString:str, enterOrTab:bool = False):
    """Click the text area of a given object, clear its text content and then types a str into it

    :param Union[dict, object] objectMap: Object to be clicked and typed into
    :param str textString: String to be enter into the object
    :param bool enterOrTab: keystroke after typing, True:<Return>, False:<Tab>

    """
    clear_text(objectMap)
    obj = __convert_map_and_move_to_object(objectMap)
    try:
        squishtest.mouseClick(obj) #type: ignore
    except Exception:
        pass
    if obj.type == "ComboBox": # type: ignore
        try:
            item = squishtest.waitForObject({"text": textString} , 10000) # type: ignore
            if item.type in ["ComboBoxItem", "Label"]:
                squishtest.mouseClick(item) # type: ignore
            elif item.type != "ComboBox":
                print(f"Item of type'{item.type}' is unsupported.")
            return
        except LookupError:
            pass
    squishtest.type(obj, textString) #type: ignore
    squishtest.nativeType("<Tab>" if enterOrTab == False else "<Return>") # type: ignore

def find_mapped_object_in_class(name: str, cls):
    """Find the mapped object of a class by given name

    :param str name: Object's name to be found
    :param cls: Class which the object belongs to.

    """
    for attr_name in dir(cls):  # Iterate through class attributes
        attr_value = getattr(cls, attr_name)
        if isinstance(attr_value, dict) and attr_value.get("text", "") == name:
            return attr_value
    return None

def get_current_item_ocr_str(obj_map):
    """Find the mapped object of a class by given name

    :param str name: Object's name to be found
    :param cls: Class which the object belongs to.

    """
    text = ""
    obj = find_object(obj_map)
    if obj:
        text = squishtest.getOcrText({}, obj) #type: ignore
        text = text.rstrip(" |") # this is used to strip the unexpected characters
    return text

def choose_item_in_list_by_scroll(obj_map:dict, item: str, scroll_direction:int = 1, click_tab:bool = True):
    """Choose the item in list by scroll of middle button of mouse

    :param obj_map: Object of the list
    :param str item: item text to be found.
    :param direction: -1 upward, 1 downward
    :param click_tab: True click tab, False not click tab before scroll.

    """
    obj = find_object(obj_map)
    squishtest.doubleClick(obj) #type: ignore
    squishtest.snooze(.1) #type: ignore
    squishtest.mouseMove(obj, obj.width-4, obj.height-10) #type: ignore
    if click_tab:
        squishtest.nativeType("<Tab>") #type: ignore
    direction = scroll_direction
    text = ""
    texts = []
    while not item in text:
        wheel(direction)
        squishtest.snooze(.1) #type: ignore
        text = squishtest.getOcrText({}, obj) #type: ignore
        texts.append(text)
        if item in text:
            return True
        if text in texts and texts.count(text) > 2:
            direction = -scroll_direction
        if text in texts and texts.count(text) > 3:
            return False
    return True

def select_item_in_list_with_acknowledge(obj_map, item: str, popup_obj_text: str="", button_str: str="" ):
    """select item in list, click the button if there is by given popup object text

    :param str item: item's text to select
    :param str popup_obj_text: text of the popup window.
    :param str button_str: text of the button to click.

    """
    if "<" in item:
        return choose_item_in_list_by_scroll(obj_map, item)

    text = squishtest.getOcrText({}, obj_map) #type: ignore
    if item in text and len(text.split(" ")[0]) <= len(item):
        return True
    org_text = text
    texts = []
    while item and not item in text:
        squishtest.mouseClick(obj_map) #type: ignore
        squishtest.nativeType(item[0]) #type: ignore
        squishtest.nativeType("<Tab>") #type: ignore
        if popup_obj_text and button_str:
            try:
                w = squishtest.waitForObject({"text": popup_obj_text}, 20) #type: ignore
                if w:
                    left_click_object({"text": button_str})
            except Exception:
                pass
        text = squishtest.getOcrText({}, obj_map) #type: ignore
        if item in text and len(text.split(" ")[0]) <= len(item):
            return True
        texts.append(text)
        if texts.count(text) > 1:
            select_item_in_list_with_acknowledge(obj_map, org_text, popup_obj_text, button_str)
            return False
    return False

def find_any_object(objects, timeout = 200):
    '''
    Find any object of a list/array
    '''
    for obj in objects:
        try:
            o = squishtest.waitForObject(obj, timeout) #type: ignore
            return o
        except Exception:
            continue
    return None

def find_object_itself(obj, uniqattr = 'id') -> opt[object]:
    '''
    Find an object via its container by a unique attribute like 'id', this is especially useful for an object that is not enabled.
    '''
    container = obj.get('container')
    attr =  obj.get(uniqattr)
    if container and attr:
        try:
            parent = squishtest.waitForObject(container) #type: ignore
            children = squishtest.object.children(parent) #type: ignore
            for child in children:
                if child.type == obj.get('type'):
                    if getattr(child, uniqattr, "") == attr or str(getattr(child, uniqattr, "")) == str(attr):
                        return child
        except Exception:
            return None
    return None

def get_children(obj) -> tuple:
    '''
    Get the chilren of an object.
    '''
    if obj and isinstance(obj, dict):
        obj = squishtest.findObject(obj) #type: ignore
    return squishtest.object.children(obj) if obj else () #type: ignore

def find_combobox_menu_item(menu_object: object, menu_item_text: str) -> opt[object]:
    '''
    Recursively search for the combo box item from the list of child objects based on the specified text
    '''
    for child in squishtest.object.children(menu_object):   #type: ignore
        if child.type == "ComboBoxItem" and hasattr(child, "text") and child.text == menu_item_text:
            return child
    return None

def get_list_items(obj) -> list:
    '''
    Get the list items from a List or a ComboBox
    '''
    itemList = []
    children = get_children(obj)
    for child in children:
        if (child.type == "ListItem" or child.type == "ComboBoxItem") and hasattr(child, "text"):
            itemList.append(child.text)
    return itemList

def click_item(obj, item:str, skipping_click_itself:bool=False, left_button:bool=True, click_screen_area:bool=False) -> bool:
    '''
    Click an item (or the area) in a list by selected left/right mouse button, skipping_click_itsel flag indicates whether
    the list needs to be clicked first.

    return True if clicked, otherwise False. It does not throw for an exception.

    :params: obj, the (list) object that has items.
             skipping_click_itself (bool), indicating if the list needs to be clicked first, True: click, False: not click
             left_button (bool), True: left button, False: right button
             click_screen_area (bool), True: click the screen area of the object, False: click the object itself
    '''
    clicked = False
    try:
        if not skipping_click_itself:
            squishtest.mouseMove(obj)
            squishtest.snooze(0.3)
            squishtest.mouseClick(obj) #type: ignore
        target = squishtest.waitForObjectItem(obj, item, 3000) # type: ignore
        if click_screen_area:
            target = squishtest.object.globalBounds(target) # type: ignore
        squishtest.mouseClick(target, squishtest.MouseButton.RightButton if left_button == False else squishtest.MouseButton.LeftButton ) #type: ignore
        clicked = True
    except Exception as ex:
        print(ex)
    return clicked

