def wait_for_object_to_disappear(targetObject: dict, timeoutInSecs: int = 5) -> bool:
    """Waits for an object to disappear

    :param dict targetObject: Object dictionary of object to be checked
    :param int timeoutInSecs: Amount of time in seconds the squish.waitFor function polls the object.exists command.
    :return bool: Success status
    """
    mSecs_converted_time: int = timeoutInSecs * 1000
    return squishtest.waitFor("squishtest.object.exists(targetObject) is False", mSecs_converted_time) #type: ignore


def wait_for_object_to_appear(targetObject: dict, timeoutInSecs: int = 5) -> bool:
    """Waits for an object to appear

    :param dict targetObject: Object dictionary of object to be checked
    :param int timeoutInSecs: Amount of time in seconds the squish.waitFor function polls the object.exists command.
    :return bool: Success status
    """
    mSecs_converted_time: int = timeoutInSecs * 1000
    return squishtest.waitFor("squishtest.object.exists(targetObject)", mSecs_converted_time) #type: ignore

def wait_for_object_one_to_disappear_or_object_two_to_appear(uiToDisappear:dict, uiToAppear:dict, timeoutInSecs:int = 100) -> str:
    """
    Waits for either the UI (busy dialog) to disappear (success)
    or the notification UI to appear (failure, notification), within a given timeout.

    :parameters:
        uiToDisappear (dict): Symbolic name of the procesing UI to disappear(busy dialog).
        uiToAppear (dict): Symbolic name of the notification UI to appear(failed dialog notification).
        timeoutInSecs (int): Maximum time to wait in seconds.

    :returns:
        str: "success", "notification", or "timeout"
    """

    try:
        squishtest.waitFor(
            "not squishtest.object.exists(uiToDisappear) or squishtest.object.exists(uiToAppear)",
            timeoutInSecs * 1000
        )
    except Exception:
        print("Timeout: neither success nor failure condition met.")
        return "timeout"

    if squishtest.object.exists(uiToAppear):
        print("Notification UI appeared — processing ends early.")
        return "notification"
    else:
        #print("Processing UI disappeared — processing ends silently.")
        return "success"

def wait_for_text_in_object(targetObject: dict, objectText: str, timeoutInSecs: int) -> bool:
    """Waits for specified text to appear in a given target object

    :param dict targetObject: Object dictionary of object to be checked
    :param dict objectText: Text to be searched in the given targetObject
    :param int timeoutInSecs: Amount of time in seconds the squish.waitFor function polls the object.exists command.
    :return bool: Success status
    """
    mSecs_converted_time: int = timeoutInSecs * 1000
    return squishtest.waitFor("objectText in squishtest.waitForObject(targetObject)['text']", mSecs_converted_time) #type: ignore

def wait_for_text_in_object_children(targetObject: dict, objectText: str, timeoutInSecs: int) -> bool:
    """Waits for specified text to appear in a given target object

    :param dict targetObject: Object dictionary of parent object to be checked
    :param dict objectText: Text to be searched in the child objects for the given targetObject
    :param int timeoutInSecs: Amount of time in seconds the squish.waitFor function polls the object.exists command.
    :return bool: Success status
    """
    mSecs_converted_time: int = timeoutInSecs * 1000
    child_object_list = get_child_objects(targetObject)
    condition = f"[child_object for child_object in child_object_list if hasattr(child_object, 'text') and '{objectText}' in child_object.text]"
    return squishtest.waitFor(condition, mSecs_converted_time) #type: ignore

def mouse_click_with_relative_x_and_y_offsets(targetObject: object, xOffsetValue: int = 0, yOffsetValue: int = 0) -> None:
    """Left mouse click on a position relative to the targetObject using x, y coordinates to offset the
    x and/or y position.

    :param object targetObject: Object whose relative position using x, y offsets is to be left mouse clicked
    :param int xOffsetValue: The x offset value relative from the targetObject. Can be a negative or positive value
    :param int yOffsetValue: The y offset value relative from the targetObject. Can be a negative or positive value
    """
    obj = __convert_map_and_move_to_object(targetObject)
    squishtest.nativeMouseClick(obj.x + xOffsetValue, obj.y + yOffsetValue, 1) #type: ignore

def mouse_click_specific_point_within_object(targetObject: object, heightOffsetValue: int = 0, widthOffsetValue: int = 0) -> None:
    """Left mouse click on a specific position within the target object by getting its bounding rectangle in
    screen coordinates as a ScreenRectangle and modifying/ offsetting the width or height by a specified value.

    :param object targetObject: Object where a specific position in its bounding rectangle is to be left mouse clicked
    :param int heightOffsetValue: The height offset value relative from the targetObject. Can be a negative or positive value
    :param int widthOffsetValue: The width offset value relative from the targetObject. Can be a negative or positive value
    """
    obj = __convert_map_and_move_to_object(targetObject)
    obj_bounding_rect = squishtest.object.globalBounds(obj)  #type: ignore
    obj_bounding_rect.height = obj_bounding_rect.height + heightOffsetValue
    obj_bounding_rect.width = obj_bounding_rect.width + widthOffsetValue
    squishtest.mouseClick(obj_bounding_rect) #type: ignore

def mouse_press_and_drag_start(sourceObject: object) -> None:
    """Press and holds primary mouse click on given object. Used in tandem with the
    "mouse_press_and_drag_end" function.

    :param object sourceObject: Object for primary mouse button to press down on
    """
    squishtest.mouseMove(sourceObject) #type: ignore
    squishtest.mousePress() #type: ignore
    time.sleep(0.5)

def mouse_press_and_drag_end(target_x: int, target_y: int) -> None:
    """Moves mouse to given XY location then releasing primary mouse button. Used after
    "mouse_press_and_drag_start" function.

    :param int target_x: X axis location of where the mouse moves to
    :param int target_y: Y axis location of where the mouse moves to
    """
    squishtest.mouseMove(target_x, target_y) #type: ignore
    time.sleep(0.5)
    squishtest.mouseRelease() #type: ignore
    time.sleep(0.5)

