def mouse_press_hold_and_release_with_positive_y_offset(targetObject: object, yOffsetValue: int, mousePressDuration: float=2) -> None:
    """Moves mouse to a given object's position using x, y coordinates and offsets the y position in the positive direction.
       Left mouse press for the specified duration and release mouse.

    :param object targetObject: Object for primary mouse button to press down on and released after a duration
    :param yOffsetValue: The y offset value in the positive direction from the targetObject
    :type yValue: int
    :param mousePressDuration: Time in seconds for the mouse press to be held
    :type mousePressDuration: float
    """
    squishtest.mousePress(targetObject.x, targetObject.y + yOffsetValue, 1) #type: ignore
    squishtest.snooze(mousePressDuration) #type: ignore
    squishtest.mouseRelease() #type: ignore

def mouse_press_hold_and_release_with_negative_y_offset(targetObject: object, yOffsetValue: int, mousePressDuration: float=2) -> None:
    """Moves mouse to a given object's position using x, y coordinates and offsets the y position in the negative direction.
       Left mouse press for the specified duration and release mouse.

    :param object targetObject: Object for primary mouse button to press down on and released after a duration
    :param yOffsetValue: The y offset value in the negative direction from the targetObject
    :type yValue: int
    :param mousePressDuration: Time in seconds for the mouse press to be held
    :type mousePressDuration: float
    """
    squishtest.mousePress(targetObject.x, targetObject.y - yOffsetValue, 1) #type: ignore
    squishtest.snooze(mousePressDuration) #type: ignore
    squishtest.mouseRelease() #type: ignore

def mouse_press_hold_and_release_with_x_and_y_offset(targetObject: object, xOffsetValue: int, yOffsetValue: int, mousePressDuration: float=2) -> None:
    """Moves mouse to a given object's position using x, y coordinates and offsets the x (left/right) and y (up/down) position
    in the specified direction. Left mouse press for the specified duration and release mouse.

    :param object targetObject: Object for primary mouse button to press down on and release after a specified duration
    :param int xOffsetValue: The x offset value from the targetObject. This can include negative numbers (i.e. left direction relative from the targetObject)
    :param int yOffsetValue: The y offset value from the targetObject. This can include negative numbers (i.e. up direction relative from the targetObject)
    :param mousePressDuration float: Time in seconds for the mouse press to be held
    """
    squishtest.mousePress(targetObject.x + xOffsetValue, targetObject.y + yOffsetValue, 1) #type: ignore
    squishtest.snooze(mousePressDuration) #type: ignore
    squishtest.mouseRelease() #type: ignore

