def is_ocr_available(targetObject: Union[dict, object] = None) -> bool:
    """Reports whether an OCR engine is configured for this Squish installation.

    Squish ships no OCR engine: Tesseract is a separate package from the Qt Customer Portal,
    and until it is installed and its path configured every OCR call raises
    "The path to the tesseract engine is not configured". Tests that read text only OCR can
    reach should probe with this and report the gap rather than dying on it.

    :param targetObject: Object to scope the probe read to. Pass one where possible -- with no
                         region the probe OCRs the whole desktop, which is slow.
    :type targetObject: Union[dict, object]
    :return: True when an OCR read succeeds, False when no engine is configured
    :rtype: bool
    """
    try:
        if targetObject is None:
            squishtest.getOcrText({}) #type: ignore
        else:
            squishtest.getOcrText({}, targetObject) #type: ignore
        return True
    except RuntimeError as error:
        message = str(error).lower()
        if "tesseract" in message or "not configured" in message or "ocr" in message:
            return False
        raise

