def wait_for_image_object(imagePath: str, parameterMapOptions: dict, searchRegion: object = None) -> opt[object]:
    """Returns the image object if found

    :param str imagePath: String path to the image file
    :param dict parameterMapOptions: Dictionary of key/value pairs to be used as search options
    :param object searchRegion: Search region to be used for the image
    :return: Found image objecy or None if not found
    :rtype: Object or None

    Example parameterMapOptions dictionary options:
    options = {
            "interval": 1000   # Time between image search retries in milliseconds (default is 1 second)
            "timeout": 30000,  # Timeout in milliseconds (e.g 30 seconds)
            "threshold": 99.0  # Matching threshold (usually fall between 99.0 and 100.0)
            "occurrence": 1    # Occurrence index (use if multiple images are matched, default is 1)
        }

    Example search region(s):
    region = waitForObject(objectClass.myObject)
    region = [waitForObject(objectClass.myObject) , waitForObject(objectClass.myObject) ]
    """
    return squishtest.waitForImage(imagePath, parameterMapOptions, searchRegion) #type: ignore

