def restore_window(hwnd:int):
    """
    Restores the window with the given handle.

    :param: hwnd (int): The handle of the window to be restored
    """
    from ctypes import windll
    ShowWindowAsync = windll.user32.ShowWindowAsync
    SW_RESTORE = 9
    ShowWindowAsync(hwnd, SW_RESTORE)

def capture_desktop_screenshot(screenshotPath: Union[str, os.PathLike] = "") -> str:
    """
    Saves the desktop screenshot for the current squish application context
    to the specified path or to the current working directory of the calling
    script if no path is provided.

    :param str screenshotPath: Path where the screenshot will be saved. If not
                               provided, defaults to current working directory.

    :return str: The full path and filename of the saved screenshot (can be used
                 with reporting tools for attaching screenshots to test reports)
    """

    date_time = time.strftime("%d%m%Y_%H%M%S%p")
    current_squish_ctx = str(squishtest.currentApplicationContext()) #type: ignore
    screenshot_filename = current_squish_ctx + "_" + date_time + ".png"

    if not screenshotPath:
        # Set saved screenshots folder to current working directory by default
        os.environ["screenshots_dir"] = os.path.join(os.getcwd(), "saved_screenshots")
    else:
        os.environ["screenshots_dir"] = str(screenshotPath)

    if not os.path.exists(os.environ["screenshots_dir"]):
        os.makedirs(os.environ["screenshots_dir"])

    # Set screenshot path and filename
    screenshot_path_and_filename=os.path.join(os.environ["screenshots_dir"], screenshot_filename)

    print(f"screenshot path and filename is: {screenshot_path_and_filename}")
    squishtest.saveDesktopScreenshot(screenshot_path_and_filename)  #type: ignore
    # return the screenshot path and filename (used for attaching to test reports)
    return screenshot_path_and_filename